import {supabase,$,node,read,session,invoke,fields,shipping,cents,status,money,busy,safeLink} from './commerce-client.js';
let warehouses=[], products=[], sources=[], context;
const productForm=$('#product-form'), warehouseForm=$('#warehouse-form');
function fill(form,values){for(const [key,value]of Object.entries(values)){const input=form.elements.namedItem(key);if(!input)continue;if(input.type==='checkbox')input.checked=!!value;else input.value=value??'';}}
function input(form,label,name,type='text',required=true,value=''){const wrapper=node('label',label);const field=node(type==='textarea'?'textarea':'input');if(type!=='textarea')field.type=type;field.name=name;field.required=required;field.value=value;wrapper.append(field);form.append(wrapper);return field;}
function submit(form,label,action,extra={},after=loadOrders){form.append(node('button',label));form.addEventListener('submit',busy(form,async()=>{await invoke(action,{...fields(form),...extra});await after();}));}
function disclosure(card,title){const details=node('details');details.append(node('summary',title));const form=node('form',null,'form-grid');details.append(form);card.append(details);return form;}
function details(card,title,value){const block=node('details');block.append(node('summary',title),node('pre',JSON.stringify(value,null,2)));card.append(block);}
function editProduct(product){const source=sources.find(s=>s.product_id===product.id)||{};productForm.reset();fill(productForm,{...product,...source,source_url:source.original_url,source_price:source.source_unit_minor==null?'':(source.source_unit_minor/100).toFixed(2),reviewed:source.verification_status==='fi_reviewed',variant_options:JSON.stringify(product.variant_options,null,2),specifications:JSON.stringify(product.specifications,null,2)});if(source.valid_until){const date=new Date(source.valid_until);productForm.elements.valid_until.value=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}productForm.scrollIntoView({behavior:'smooth',block:'start'});}
async function loadProducts(){[products,sources]=await Promise.all([read('fi_shop_products'),read('fi_product_sources')]);$('#product-list').replaceChildren();$('#evidence-products').replaceChildren();for(const product of products){const card=node('article',null,'card');card.append(node('span',product.status,'badge'),node('h3',product.title));const source=sources.find(s=>s.product_id===product.id);if(source){card.append(safeLink(source.canonical_url,'Open source listing'));card.append(node('p',source.source_unit_minor==null?'Source price unconfirmed':`${source.source_currency} ${(source.source_unit_minor/100).toFixed(2)} · ${source.verification_status.replaceAll('_',' ')}`));}const edit=node('button','Edit','secondary');edit.onclick=()=>editProduct(product);card.append(node('div',null,'toolbar')).append(edit);$('#product-list').append(card);const option=node('option',product.title);option.value=product.id;$('#evidence-products').append(option);}}
productForm.addEventListener('submit',busy(productForm,async()=>{const values=fields(productForm);await invoke('save_product',{...values,id:values.id||undefined,source_unit_minor:values.source_price?cents(values.source_price):null,fx_to_aud:values.fx_to_aud?Number(values.fx_to_aud):null,source_currency:values.source_currency||null,min_quantity:Number(values.min_quantity),variant_options:JSON.parse(values.variant_options),specifications:JSON.parse(values.specifications),valid_until:values.valid_until?new Date(values.valid_until).toISOString():null,reviewed:values.reviewed==='on',image_permission_confirmed:values.image_permission_confirmed==='on'});await loadProducts();}));
$('#new-product').onclick=()=>{productForm.reset();productForm.elements.id.value='';};
$('#evidence-form').addEventListener('submit',busy($('#evidence-form'),async()=>{await invoke('add_evidence',fields($('#evidence-form')));}));
async function loadWarehouses(){warehouses=await read('fi_warehouses');$('#warehouse-list').replaceChildren();if(!warehouses.length)$('#warehouse-list').append(node('p','No warehouse configured. Add the address here when ready.','empty'));for(const w of warehouses){const card=node('article',null,'card');card.append(node('h3',w.name),node('span',w.active?'Receiving enabled':'Inactive','badge'),node('p',Object.values(w.address).filter(Boolean).join(', ')));const edit=node('button','Edit warehouse','secondary');edit.onclick=()=>{fill(warehouseForm,{...w,...w.address,warehouse_name:w.name});warehouseForm.scrollIntoView({behavior:'smooth'});};card.append(edit);$('#warehouse-list').append(card);}}
warehouseForm.addEventListener('submit',busy(warehouseForm,async()=>{const values=fields(warehouseForm);await invoke('save_warehouse',{...values,id:values.id||undefined,name:values.warehouse_name,address:shipping({...values,name:values.contact_name}),active:values.active==='on'});await loadWarehouses();}));
$('#new-warehouse').onclick=()=>{warehouseForm.reset();warehouseForm.elements.id.value='';};
$('#settings-form').addEventListener('submit',busy($('#settings-form'),async()=>{await invoke('save_settings',fields($('#settings-form')));context=await invoke('context');}));
function quoteForm(card,order){const form=disclosure(card,'Prepare inclusive quote');const labels={inbound_shipping_minor:'Supplier → warehouse freight',inspection_minor:'Inspection / handling',outbound_shipping_minor:'Warehouse → customer freight',duties_minor:'Import duties',tax_minor:'Applicable tax',payment_cost_minor:'Processing cost allowance'};for(const [key,label]of Object.entries(labels)){const field=input(form,`${label} (AUD)`,key,'number');field.min='0';field.step='.01';field.placeholder='Confirm amount, including zero';}input(form,'Tax treatment / basis','tax_note','textarea');input(form,'Delivery scope and confirmed destination','delivery_scope','textarea');const button=node('button','Approve and lock inclusive quote');form.append(button);form.addEventListener('submit',busy(form,async()=>{const values=fields(form);const costs=Object.fromEntries(Object.keys(labels).map(k=>[k,cents(values[k])]));await invoke('approve_quote',{order_id:order.id,costs,tax_note:values.tax_note,delivery_scope:values.delivery_scope});await loadOrders();}));}
function purchaseForm(card,order){const form=disclosure(card,'Prepare supplier purchase instructions');const wrapper=node('label','Receiving warehouse');const select=node('select');select.name='warehouse_id';select.required=true;for(const w of warehouses.filter(w=>w.active)){const option=node('option',w.name);option.value=w.id;select.append(option);}wrapper.append(select);form.append(wrapper);submit(form,'Prepare purchase instructions','prepare_purchase',{order_id:order.id});}
function inspectForm(card,po){const form=disclosure(card,'Record full inspection');const checked=input(form,'Units inspected','quantity_checked','number',true,po.quantity);checked.min='1';const passed=input(form,'Units passed','quantity_passed','number',true);passed.min='0';for(const [key,label]of Object.entries({correct_variant:'Correct model and variant',dimensions:'Dimensions checked',finish:'Finish / damage checked',function:'Function checked',packaging:'Packaging checked'})){const wrapper=node('label',null,'check');const field=node('input');field.type='checkbox';field.name=key;wrapper.append(field,node('span',label));form.append(wrapper);}input(form,'Inspection notes','notes','textarea',false);const file=input(form,'Inspection photos / PDF (10 MB each)','evidence','file',false);file.multiple=true;file.accept='image/jpeg,image/png,image/webp,application/pdf';form.append(node('button','Record inspection'));let evidencePaths=[];form.addEventListener('submit',busy(form,async()=>{const values=fields(form);if(!evidencePaths.length){for(const image of file.files){if(image.size>10485760)throw new Error('Each evidence file must be 10 MB or less.');const path=`inspections/${po.id}/${crypto.randomUUID()}-${image.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error}=await supabase.storage.from('fi-commerce-evidence').upload(path,image);if(error)throw error;evidencePaths.push(path);}}await invoke('inspect',{purchase_order_id:po.id,quantity_checked:Number(values.quantity_checked),quantity_passed:Number(values.quantity_passed),notes:values.notes,checklist:Object.fromEntries(['correct_variant','dimensions','finish','function','packaging'].map(k=>[k,values[k]==='on'])),evidence_paths:evidencePaths});await loadOrders();}));}
function procurement(card,po){const panel=node('div',null,'card');panel.append(node('h3',`Supplier purchase · ${po.status.replaceAll('_',' ')}`),node('p',`${po.quantity} units · ${po.source_snapshot.supplier_variant||'Variant not supplied'}`),safeLink(po.source_snapshot.canonical_url,'Open saved supplier listing'));details(panel,'Frozen warehouse destination',po.warehouse_snapshot);if(po.status==='pending_purchase'){const form=disclosure(panel,'Record supplier order');input(form,'Supplier order reference','external_order_id');submit(form,'Mark purchased','update_purchase',{purchase_order_id:po.id,transition:'ordered'});}if(po.status==='ordered'){const form=disclosure(panel,'Record inbound shipment');input(form,'Carrier','carrier');input(form,'Tracking number','tracking_number');input(form,'Tracking URL','tracking_url','url',false);submit(form,'Save inbound tracking','update_purchase',{purchase_order_id:po.id,transition:'inbound'});const receipt=node('form',null,'toolbar');submit(receipt,'Confirm warehouse receipt','update_purchase',{purchase_order_id:po.id,transition:'received'});panel.append(receipt);}if(po.status==='received')inspectForm(panel,po);card.append(panel);}
async function loadOrders(){const {data:orders,error}=await supabase.from('fi_shop_orders').select('*,fi_shop_order_items(*),fi_shop_payments(*),fi_order_costs(*),fi_purchase_orders(*),fi_order_shipments(*)').order('created_at',{ascending:false}).limit(100);if(error)throw error;const list=$('#order-list');list.replaceChildren();if(!orders.length)list.append(node('p','No customer orders yet. Published products can receive quote requests from the catalogue.','empty'));for(const order of orders){const card=node('article',null,'card');card.append(node('span',order.status.replaceAll('_',' '),'badge'),node('h3',order.reference),node('p',`${order.customer_email} · ${order.customer_phone}`));for(const item of order.fi_shop_order_items)card.append(node('p',`${item.quantity} × ${item.title}`));card.append(node('p',Object.values(order.shipping_address).filter(Boolean).join(', '),'muted'));if(order.total_minor!=null)card.append(node('p',`${money(order.total_minor)} AUD inclusive`,'price'));if(order.fulfillment_hold)card.append(node('p','Fulfilment hold ; reconcile refunds, disputes or returns before proceeding.','notice'));if(order.fi_order_costs)details(card,'Internal cost and source snapshot',order.fi_order_costs);if(order.fi_shop_payments)details(card,'Payment record',order.fi_shop_payments);if(order.status==='awaiting_quote')quoteForm(card,order);if(['paid','purchasing'].includes(order.status)&&!order.fulfillment_hold)purchaseForm(card,order);for(const po of order.fi_purchase_orders)procurement(card,po);if(['inspecting','ready_to_ship'].includes(order.status)){const form=disclosure(card,'Dispatch to customer');input(form,'Carrier','carrier');input(form,'Tracking number','tracking_number');input(form,'Tracking URL','tracking_url','url',false);submit(form,'Dispatch inspected order','dispatch',{order_id:order.id});}if(order.status==='shipped'){const form=node('form',null,'toolbar');submit(form,'Confirm customer delivery','deliver',{order_id:order.id});card.append(form);}if(order.paid_at){const form=disclosure(card,'Record a return / issue');input(form,'Reason','reason','textarea');submit(form,'Record issue and hold fulfilment','record_return',{order_id:order.id});}for(const shipment of order.fi_order_shipments)card.append(node('p',`${shipment.leg.replaceAll('_',' ')} · ${shipment.carrier} · ${shipment.tracking_number} · ${shipment.status}`));list.append(card);}}
$('#refresh-orders').onclick=()=>loadOrders().catch(error=>status(error.message,true));
try{await session(true);context=await invoke('context');if(!context.team)throw new Error('This workspace is restricted to FI team accounts.');$('#workspace').hidden=false;$('#access-note').textContent=`FI team access confirmed. Checkout: ${context.checkout_enabled?context.payment_mode:'not activated'}. Supplier purchasing: manual.`;fill($('#settings-form'),{pricing_mode:context.pricing_mode});const categories=await read('fi_shop_categories');for(const c of categories){const option=node('option',c.name);option.value=c.slug;$('#categories').append(option);}await Promise.all([loadProducts(),loadWarehouses()]);await loadOrders();}catch(error){status(error.message,true);$('#access-note').textContent='Sign in with an authorised FI team account to manage commerce.';}
